import { openAttribute } from "./beanref";
import { startTagAt } from "./dataformats";

/**
 * The connector catalog (media/redb-route-catalog.json, generated by `redb-route-xml catalog`): one
 * component per scheme with its options. The graph's endpoint panel and the registry-reference hints
 * read it through the same scheme index.
 */

/** One option of a component. `reference` marks an option that names a registry object. */
export interface CatalogOption {
    name: string;
    type: string;
    default?: string | null;
    sensitive: boolean;
    enumValues?: string[];
    /** The expected type ("Full.Name, Assembly"), or "object" when the code gives none. Absent: not a reference. */
    reference?: string;
}

export interface CatalogComponent {
    scheme: string;
    alternateSchemes: string[];
    pathSynonym?: string | null;
    /** The only side of a one-sided component; absent means both (a consumer and a producer). */
    role?: "producer" | "consumer";
    options: CatalogOption[];
}

/**
 * The components by scheme, lower case: each scheme, its alternate schemes, and the everyday spellings
 * the catalog declares no alternate for (a `from uri="http://..."` is the https component's endpoint).
 */
export function catalogByScheme(components: readonly CatalogComponent[]): Map<string, CatalogComponent> {
    const byScheme = new Map<string, CatalogComponent>();
    for (const component of components) {
        byScheme.set(component.scheme, component);
        for (const alternate of component.alternateSchemes ?? [])
            byScheme.set(alternate, component);
    }
    for (const [alias, canonical] of [["http", "https"], ["ws", "wss"]] as const) {
        const component = byScheme.get(canonical);
        if (component && !byScheme.has(alias)) byScheme.set(alias, component);
    }
    return byScheme;
}

/** The option of a component by name, case-insensitively, as the options bind. */
export function findOption(component: CatalogComponent, name: string): CatalogOption | undefined {
    const wanted = name.toLowerCase();
    return component.options.find(o => o.name.toLowerCase() === wanted);
}

/** Where a value of a registry-reference option is being typed, and the option. */
export interface CatalogReferencePosition {
    /** The start of the name typed so far, after the `#` when one is typed. */
    replaceFrom: number;
    /** Whether the `#` is already typed; otherwise completion inserts it with the name. */
    hashTyped: boolean;
    option: CatalogOption;
}

/** A whole value that is a name so far, with or without its `#`. */
const NAME_VALUE = /^(#?)([A-Za-z0-9_.\-]*)$/;

/** `scheme:path?a=1&key=value` with the offset at the end of `value`. */
const URI_QUERY_VALUE = /^([A-Za-z][A-Za-z0-9+.\-]*):[^?]*\?(?:[^&]*&)*([^=&]+)=(#?)([A-Za-z0-9_.\-]*)$/;

/**
 * The value of a component option the catalog marks as a registry reference, empty or a name so far
 * (with or without its `#`): a query value of an endpoint URI (`uri="sql:select 1?dataSource=|"`) or an attribute of the
 * structured endpoint form (`<sql dataSource="|">`). The scheme is matched with its alternates and the
 * option name case-insensitively.
 */
export function catalogReferencePosition(
    text: string, offset: number, byScheme: ReadonlyMap<string, CatalogComponent>): CatalogReferencePosition | null {
    const open = openAttribute(text, offset);
    if (!open)
        return null;
    const query = URI_QUERY_VALUE.exec(open.value);
    if (query) {
        const option = referenceOption(byScheme, query[1], queryKey(query[2]));
        return option ? { replaceFrom: offset - query[4].length, hashTyped: query[3] === "#", option } : null;
    }
    const name = NAME_VALUE.exec(open.value);
    if (!name)
        return null;
    const option = referenceOption(byScheme, open.element, open.attribute);
    return option ? { replaceFrom: offset - name[2].length, hashTyped: name[1] === "#", option } : null;
}

/**
 * The hover of a registry-reference option: on an attribute name of the structured endpoint form, or
 * on a query key of an endpoint URI value.
 */
export function catalogReferenceHover(
    text: string, offset: number, byScheme: ReadonlyMap<string, CatalogComponent>): string | null {
    const tag = startTagAt(text, offset);
    if (!tag)
        return null;
    for (const attribute of tag.attributes) {
        if (attribute.nameStart <= offset && offset < attribute.nameEnd) {
            const option = referenceOption(byScheme, tag.element, attribute.name);
            return option ? describeReference(option) : null;
        }
        if (attribute.valueStart >= 0 && attribute.valueStart <= offset && offset < attribute.valueEnd) {
            const scheme = /^([A-Za-z][A-Za-z0-9+.\-]*):/.exec(attribute.value)?.[1];
            const query = attribute.value.indexOf("?");
            const at = offset - attribute.valueStart;
            if (!scheme || query < 0 || at <= query)
                return null;
            const keyStart = Math.max(attribute.value.lastIndexOf("&", at - 1), query) + 1;
            const equals = attribute.value.indexOf("=", keyStart);
            if (equals < 0 || at >= equals)
                return null;
            const option = referenceOption(byScheme, scheme, queryKey(attribute.value.slice(keyStart, equals)));
            return option ? describeReference(option) : null;
        }
    }
    return null;
}

function referenceOption(
    byScheme: ReadonlyMap<string, CatalogComponent>, scheme: string, name: string): CatalogOption | undefined {
    const component = byScheme.get(scheme.toLowerCase());
    const option = component ? findOption(component, name) : undefined;
    return option?.reference !== undefined ? option : undefined;
}

/** What the item detail says about the expected type: nothing when the code gives none. */
export function expectedType(option: CatalogOption): string | null {
    return option.reference !== undefined && option.reference !== "object" ? option.reference : null;
}

function describeReference(option: CatalogOption): string {
    const expected = expectedType(option);
    return `**${option.name}** names a registry object: \`#name\` of a \`<bean>\`.`
        + (expected ? `\n\nExpects \`${expected}\`.` : "");
}

/** A query key as written in XML, where the separator is spelled `&amp;`. */
function queryKey(raw: string): string {
    return raw.startsWith("amp;") ? raw.slice(4) : raw;
}
